# context-transfer-error.schema.json

Generated, complete JSON Schema reference. Required/default/conditional rules are not inferred.

```json
{
  "$id": "https://coding-hermes.local/chd32/schemas/context-transfer-error.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "properties": {
    "audit_ref": {
      "pattern": "^/chd/audit/[A-Za-z0-9._/-]+$",
      "type": "string"
    },
    "code": {
      "enum": [
        "cross_profile_native_fork_unsupported",
        "adapter_capability_probe_required",
        "context_import_not_authorized",
        "context_import_unavailable",
        "target_profile_invalid",
        "policy_owner_missing"
      ]
    },
    "error_id": {
      "pattern": "^ctxerr-[a-z0-9-]+$",
      "type": "string"
    },
    "message": {
      "minLength": 1,
      "type": "string"
    },
    "probe_ref": {
      "pattern": "^probe-[a-z0-9-]+$",
      "type": [
        "string",
        "null"
      ]
    },
    "request_id": {
      "pattern": "^ctxreq-[a-z0-9-]+$",
      "type": "string"
    },
    "schema_version": {
      "const": 1
    },
    "source_request": {
      "pattern": "^/chd/context-transfer/requests/ctxreq-[a-z0-9-]+$",
      "type": "string"
    },
    "status": {
      "const": "rejected"
    }
  },
  "required": [
    "schema_version",
    "request_id",
    "error_id",
    "status",
    "code",
    "message",
    "source_request",
    "audit_ref"
  ],
  "title": "CHD cross-profile context transfer error",
  "type": "object"
}
```
